type Product {
  id: Int!
  name: String!
  description: String!
  price: Int64!
}
type ProductListResponse {
  id: Int!
  name: String!
  description: String!
  price: Int64!
}
type ErrorResponse {
  code: String!
  message: String!
}
type Query {
  """
  Get a single product by ID
  """
  product(id: Int!): Product
  """
  Get a list of all products
  """
  products: [Product!]!
}

// Product is the resolver for the product field.
func (r *queryResolver) Product(ctx context.Context, id int) (*model.Product, error) {
	product, err := r.ProductService.GetProductByID(ctx, int32(id))
	if err != nil {
		return nil, fmt.Errorf("failed to get product: %w", err)
	}
	return &model.Product{
		ID: int(product.ID), Name: product.Name, Description: product.Description, Price: product.Price,
	}, nil
}

// Products is the resolver for the products field.
func (r *queryResolver) Products(ctx context.Context) ([]*model.Product, error) {
	products, err := r.ProductService.ListProducts(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list products: %w", err)
	}
	var result []*model.Product
	for _, p := range products {
		result = append(result, &model.Product{
			ID: int(p.ID), Name: p.Name, Description: p.Description, Price: p.Price,
		})
	}
	return result, nil
}
